import { z } from 'zod';
import { getAuthHeaders } from '../utils/auth.js';

/**
 * Agent Heartbeat Tool (MCP-010)
 * 
 * Reports the agent's current state to the Orbiter backend.
 * The backend updates the session record and broadcasts via WebSocket.
 * session_id is auto-generated by the MCP server - Claude never needs to provide it.
 */

const HeartbeatInputSchema = z.object({
    session_id: z.string().uuid().optional()
        .describe('Auto-generated session UUID (do not provide - injected automatically)'),
    state: z.enum(['idle', 'working', 'waiting', 'error'])
        .describe('Current agent state'),
    task: z.string().optional()
        .describe('Description of what the agent is currently doing'),
});

type HeartbeatInput = z.infer<typeof HeartbeatInputSchema>;

export const agentHeartbeatTool = {
    name: 'agent_heartbeat',
    description: `Report the agent's current working state to Orbiter Dev.

Use this tool to keep the user informed about what you're doing:
- Call with state "working" when starting a task
- Call with state "waiting" when blocked on user input
- Call with state "idle" when between tasks
- Call with state "error" when something went wrong

IMPORTANT: Call this tool at least every 30 seconds during active work.
The backend monitors heartbeat freshness - if no heartbeat is received
within 60 seconds, the user gets a push notification:
"Agent stopped responding - Kill?"

This acts as a dead-man switch to protect against hung or stalled agents.
The user will see your state as a live badge on their mobile app.`,
    inputSchema: {
        type: 'object',
        properties: {
            state: {
                type: 'string',
                enum: ['idle', 'working', 'waiting', 'error'],
                description: 'Current agent state',
            },
            task: {
                type: 'string',
                description: 'Description of current task',
            },
        },
        required: ['state'],
    },
};

export async function handleAgentHeartbeat(
    args: unknown
): Promise<{ content: Array<{ type: string; text: string }> }> {
    // Lazy import to avoid circular dependency
    const { SESSION_ID } = await import('../index.js');
    
    const input = HeartbeatInputSchema.parse(args);
    const sessionId = input.session_id || SESSION_ID;
    const serverUrl = process.env.ORBITER_SERVER_URL || 'https://api.orbiterdev.ai';

    try {
        const response = await fetch(`${serverUrl}/api/v1/agent/heartbeat`, {
            method: 'POST',
            headers: getAuthHeaders(),
            body: JSON.stringify({
                session_id: sessionId,
                state: input.state,
                task: input.task || '',
            }),
        });

        if (!response.ok) {
            const text = await response.text();
            throw new Error(`Server responded with ${response.status}: ${text}`);
        }

        const data: any = await response.json();

        return {
            content: [{
                type: 'text',
                text: JSON.stringify({
                    success: true,
                    message: `Agent state updated to "${input.state}"`,
                    data,
                }, null, 2),
            }],
        };
    } catch (error: any) {
        return {
            content: [{
                type: 'text',
                text: JSON.stringify({
                    success: false,
                    error: error.message,
                    hint: 'Ensure Orbiter Backend is running',
                }, null, 2),
            }],
        };
    }
}
